package org.dextur.reputation.storage;
import java.nio.file.Path;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.dextur.reputation.api.*;
import org.dextur.reputation.domain.recovery.*;
import org.dextur.reputation.domain.recovery.RecoveryData.*;
import static org.dextur.reputation.storage.RecoveryFixtures.*;
import static org.junit.jupiter.api.Assertions.*;
final class RecoveryContract {
    static void lifecycle(StorageBackend b,Path d)throws Exception{
        seed(b,d,rules(RecoveryRules.Type.ACTIVE_PLAYTIME));var start=request(Command.START,NOW);var first=b.recover(start);assertEquals(RecoverySnapshot.Status.ACTIVE,first.snapshot().status());assertEquals(first.state(),b.recover(start).state());assertThrows(IllegalStateException.class,()->b.recover(request(Command.START,NOW)));b.recover(sample(NOW,0,0));
        var change=b.recover(sample(NOW.plusSeconds(10),10,10));assertEquals(5,change.profile().systemScore());assertEquals(-96,change.profile().visibleScore());assertEquals("OFFENDER",change.profile().tier());assertEquals(1,change.snapshot().rewards().size());assertEquals("two",change.snapshot().stageId());assertEquals(5000,change.state().lifetimeTrust());assertEquals(505000,change.trust().score());assertTrue(change.events().stream().anyMatch(e->e.kind()==RecoveryService.Kind.REWARD_GRANTED));
        var completed=b.recover(request(Command.READ,NOW.plusSeconds(20)));assertEquals(RecoverySnapshot.Status.COMPLETED,completed.snapshot().status());assertEquals(12,completed.profile().systemScore());assertEquals("SUSPICIOUS",completed.profile().tier());assertEquals(10000,completed.state().lifetimeTrust());assertEquals(510000,completed.trust().score());assertEquals(0,b.snapshot().votes().size());var before=b.snapshot();assertTrue(b.recover(request(Command.READ,NOW.plusSeconds(21))).events().isEmpty());assertEquals(before,b.snapshot());assertThrows(IllegalStateException.class,()->b.recover(request(Command.START,NOW.plusSeconds(22))));
        b.setLanguage(PLAYER,org.dextur.reputation.domain.PlayerLanguage.ru_RU);b.getOrCreate(UUID.randomUUID(),"global");
        var outgoing=ProtectionFixtures.vote(PLAYER,UUID.randomUUID(),VoteType.POSITIVE,"after recovery");b.vote("global",outgoing,new org.dextur.reputation.domain.VoterFacts(true,true,108000,NOW.minusSeconds(604800),true,true,true),ProtectionFixtures.eligibility(),NOW.plusSeconds(23));
        assertEquals(10000,b.inspectTrust(PLAYER,"global").explanation().get("rehabilitation_credit"));assertEquals(12,b.snapshot().recovery().get(PLAYER,"global").lifetimeReward());
    }
    static void concurrency(StorageBackend b,Path d)throws Exception{
        seed(b,d,rules(RecoveryRules.Type.ACTIVE_PLAYTIME));try(var executor=Executors.newFixedThreadPool(8)){var starts=new ArrayList<Future<Boolean>>();for(int i=0;i<32;i++)starts.add(executor.submit(()->{try{b.recover(request(Command.START,NOW));return true;}catch(IllegalStateException e){return false;}}));int success=0;for(var f:starts)if(f.get())success++;assertEquals(1,success);b.recover(sample(NOW,0,0));var calls=new ArrayList<Future<Change>>();var one=sample(NOW.plusSeconds(10),10,10);for(int i=0;i<32;i++)calls.add(executor.submit(()->b.recover(one)));for(var f:calls)f.get();assertEquals(1,b.snapshot().recovery().get(PLAYER,"global").rewards().size());assertEquals(5,b.getOrCreate(PLAYER,"global").systemScore());}
    }
    static void pause(StorageBackend b,Path d)throws Exception{
        seed(b,d,rules(RecoveryRules.Type.ACTIVE_PLAYTIME));b.recover(request(Command.START,NOW));b.recover(sample(NOW,0,0));b.recover(sample(NOW.plusSeconds(4),4,4));b.recover(request(Command.PAUSE,NOW.plusSeconds(4)));b.recover(sample(NOW.plusSeconds(20),20,20));assertEquals(4,b.snapshot().recovery().get(PLAYER,"global").current().progress().get("first"));b.recover(request(Command.RESUME,NOW.plusSeconds(20)));assertEquals(5,b.recover(sample(NOW.plusSeconds(26),26,26)).profile().systemScore());b.recover(request(Command.LOCK,NOW.plusSeconds(27)));assertEquals(RecoverySnapshot.Status.PAUSED,b.recover(request(Command.READ,NOW.plusSeconds(28))).snapshot().status());assertThrows(IllegalStateException.class,()->b.recover(request(Command.RESUME,NOW.plusSeconds(29))));b.recover(request(Command.UNLOCK,NOW.plusSeconds(30)));b.recover(request(Command.RESUME,NOW.plusSeconds(30)));assertEquals(RecoverySnapshot.Status.COMPLETED,b.recover(request(Command.READ,NOW.plusSeconds(40))).snapshot().status());
    }
    static void provider(StorageBackend b,Path d)throws Exception{
        seed(b,d,rules(RecoveryRules.Type.EXTERNAL));var start=b.recover(request(Command.START,NOW));assertEquals(RecoverySnapshot.Status.PAUSED,start.snapshot().status());Set<String> providers=Set.of("test-provider@1");b.recover(request(UUID.randomUUID(),Command.RESUME,NOW,0,0,SESSION,false,ZERO,"",0,providers));UUID enrollment=start.state().current().id();var event=request(UUID.randomUUID(),Command.EXTERNAL,NOW.plusSeconds(1),0,0,SESSION,false,enrollment,"first",10,providers);var accepted=b.recover(event);assertEquals(1,accepted.snapshot().rewards().size());assertEquals(accepted.state(),b.recover(event).state());assertThrows(IllegalStateException.class,()->b.recover(request(UUID.randomUUID(),Command.EXTERNAL,NOW.plusSeconds(2),0,0,SESSION,false,ZERO,"first",10,providers)));assertThrows(IllegalArgumentException.class,()->b.recover(request(event.operation(),Command.EXTERNAL,NOW.plusSeconds(3),0,0,SESSION,false,enrollment,"first",9,providers)));
    }
    static void daysAndReplay(StorageBackend b,Path d)throws Exception{
        var stage=new RecoveryRules.Stage("days",text("days"),"BOOK",List.of(objective("days",RecoveryRules.Type.LOGIN_DAYS,2)),5,0);seed(b,d,program(List.of(stage),5,10));b.recover(request(Command.START,NOW));b.recover(sample(NOW,0,0));var first=b.recover(sample(NOW.plusSeconds(2),2,2));assertEquals(1,first.state().loginDays().size());b.recover(sample(NOW.plusSeconds(4),4,4));assertEquals(1,b.snapshot().recovery().get(PLAYER,"global").loginDays().size());UUID next=UUID.randomUUID();b.recover(request(UUID.randomUUID(),Command.SAMPLE,NOW.plusSeconds(5),0,0,next,true,ZERO,"",0,Set.of()));long play=b.snapshot().recovery().get(PLAYER,"global").play();b.recover(sample(NOW.plusSeconds(6),6,6));assertEquals(play,b.snapshot().recovery().get(PLAYER,"global").play());var second=b.recover(request(UUID.randomUUID(),Command.SAMPLE,NOW.plusSeconds(86400),2,2,next,false,ZERO,"",0,Set.of()));assertEquals(RecoverySnapshot.Status.EXPIRED,second.snapshot().status());
    }
    static void frozen(StorageBackend b,Path d)throws Exception{seed(b,d,rules(RecoveryRules.Type.ACTIVE_PLAYTIME));b.recover(request(Command.START,NOW));var old=b.snapshot().recovery().get(PLAYER,"global").current().definition();b.recovery(program(List.of(new RecoveryRules.Stage("changed",text("changed"),"BOOK",List.of(objective("changed",RecoveryRules.Type.WAIT_PERIOD,1)),100,0)),100,200));assertEquals(old,b.recoveryDefinition(PLAYER,"global"));b.recover(sample(NOW,0,0));var completed=b.recover(sample(NOW.plusSeconds(10),10,10));assertEquals(5,completed.profile().systemScore());assertEquals("two",completed.snapshot().stageId());}
    static void disabled(StorageBackend b,Path d)throws Exception{var rules=rules(RecoveryRules.Type.ACTIVE_PLAYTIME);seed(b,d,rules);b.recover(request(Command.START,NOW));b.recover(sample(NOW,0,0));java.nio.file.Files.createDirectories(d);java.nio.file.Files.writeString(d.resolve("recovery.yml"),"config-version: 1\nrecovery:\n  enabled: false\n");b.recovery(org.dextur.reputation.application.RecoveryConfiguration.load(d));assertEquals(RecoverySnapshot.Status.PAUSED,b.snapshot().recovery().get(PLAYER,"global").current().status());assertTrue(b.snapshot().recovery().get(PLAYER,"global").rewards().isEmpty());assertThrows(IllegalStateException.class,()->b.recover(request(Command.START,NOW.plusSeconds(1))));b.recovery(rules);assertEquals(RecoverySnapshot.Status.PAUSED,b.recover(request(Command.READ,NOW.plusSeconds(1))).snapshot().status());b.recover(request(Command.RESUME,NOW.plusSeconds(1)));b.recover(sample(NOW.plusSeconds(1),1,0));assertEquals(5,b.recover(sample(NOW.plusSeconds(11),11,10)).profile().systemScore());}
    static void automatic(StorageBackend b,Path d)throws Exception{java.nio.file.Files.createDirectories(d);java.nio.file.Files.writeString(d.resolve("recovery.yml"),"config-version: 1\nrecovery:\n  enrollment:\n    automatic: true\n    manual: false\n");var rules=org.dextur.reputation.application.RecoveryConfiguration.load(d);seed(b,d,rules);assertEquals(RecoverySnapshot.Status.ACTIVE,b.recover(sample(NOW,0,0)).snapshot().status());assertThrows(IllegalStateException.class,()->b.recover(request(Command.START,NOW.plusSeconds(1))));}

}
